-- Portfolio DEUST APN V2 — schéma initial Supabase (PostgreSQL)
-- À appliquer dans un projet de TEST après validation DSI/DPO. Ne pas utiliser directement en production.
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('student','teacher','tutor','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.evaluation_level as enum ('not_addressed','not_acquired','in_progress','acquired'); exception when duplicate_object then null; end $$;
do $$ begin create type public.competency_kind as enum ('transversal','activity_specific'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,first_name text,last_name text,created_at timestamptz default now());
create table if not exists public.user_roles(user_id uuid references public.profiles(id) on delete cascade,role public.app_role not null,primary key(user_id,role));
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,address text,created_at timestamptz default now());
create table if not exists public.activities(id uuid primary key default gen_random_uuid(),name text unique not null);
insert into public.activities(name) values ('Escalade'),('PAH'),('Trail'),('Course d’orientation'),('VTT'),('Kayak'),('Stand Up Paddle'),('Voile') on conflict do nothing;
create table if not exists public.competency_domains(id uuid primary key default gen_random_uuid(),name text unique not null,sort_order int not null);
insert into public.competency_domains(name,sort_order) values ('Gestion de la sécurité',1),('Maîtrise de l’activité',2),('Gestion du matériel',3),('Préparation des séances',4),('Contact avec le public accueilli',5),('Implication dans la structure',6) on conflict do nothing;
create table if not exists public.competencies(id uuid primary key default gen_random_uuid(),domain_id uuid references public.competency_domains(id) on delete cascade,activity_id uuid references public.activities(id),kind public.competency_kind not null,title text not null,description text,active boolean default true,check((kind='transversal' and domain_id is not null and activity_id is null) or (kind='activity_specific' and activity_id is not null)));
insert into public.competencies(domain_id,kind,title) select d.id,'transversal',v.title from (values
('Gestion de la sécurité','Identifie les enjeux de sécurité'),('Gestion de la sécurité','Présente les règles de sécurité'),('Gestion de la sécurité','Identifie les prises de risque et agit pour éviter un accident'),
('Maîtrise de l’activité','Connaît les spécificités de l’activité'),('Maîtrise de l’activité','Utilise la terminologie adaptée'),('Maîtrise de l’activité','Distingue et hiérarchise les niveaux de pratique'),
('Gestion du matériel','Utilise le matériel de manière adaptée'),('Gestion du matériel','Vérifie, gère et entretient le matériel'),('Gestion du matériel','Anticipe et prépare le matériel nécessaire'),
('Préparation des séances','Utilise une méthodologie et un document pertinent'),('Préparation des séances','Planifie les différentes étapes de la séance'),('Préparation des séances','Anticipe les dispositifs, consignes et régulations'),
('Contact avec le public accueilli','Adopte une posture et une communication respectueuses'),('Contact avec le public accueilli','Mobilise le groupe avec dynamisme'),('Contact avec le public accueilli','Régule et adapte son intervention'),
('Implication dans la structure','Observe et questionne le fonctionnement'),('Implication dans la structure','Adopte une posture professionnelle'),('Implication dans la structure','Est force de proposition')
) as v(domain,title) join public.competency_domains d on d.name=v.domain where not exists(select 1 from public.competencies c where c.domain_id=d.id and c.title=v.title);
create table if not exists public.internships(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,organization_id uuid references public.organizations(id),study_year smallint not null check(study_year in (1,2)),period_type text not null check(period_type in ('spread','block','apprenticeship')),starts_on date,ends_on date,expected_hours numeric(7,2) not null default 0,created_at timestamptz default now());
create table if not exists public.internship_tutors(internship_id uuid references public.internships(id) on delete cascade,tutor_id uuid references public.profiles(id) on delete cascade,invited_at timestamptz default now(),accepted_at timestamptz,primary key(internship_id,tutor_id));
create table if not exists public.internship_hours(id uuid primary key default gen_random_uuid(),internship_id uuid references public.internships(id) on delete cascade,work_date date not null,hours numeric(5,2) not null check(hours>0),description text,status text not null default 'declared' check(status in ('declared','validated','rejected')),validated_by uuid references public.profiles(id),created_at timestamptz default now());
create table if not exists public.experiences(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,internship_id uuid references public.internships(id) on delete set null,activity_id uuid references public.activities(id),experienced_on date not null,duration_hours numeric(5,2),mission text not null,audience text,reflection text,visibility text not null default 'student_and_assigned_staff',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.evaluations(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,competency_id uuid not null references public.competencies(id),experience_id uuid references public.experiences(id) on delete set null,internship_id uuid references public.internships(id) on delete set null,evaluator_id uuid not null references public.profiles(id),evaluator_role public.app_role not null,level public.evaluation_level not null,comment text,evaluated_at timestamptz default now(),created_at timestamptz default now());
create table if not exists public.evidence_files(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id) on delete cascade,experience_id uuid references public.experiences(id) on delete cascade,competency_id uuid references public.competencies(id),storage_path text not null,file_name text not null,mime_type text,created_at timestamptz default now());
create or replace function public.has_role(r public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=r); $$;
create or replace function public.assigned_to_student(s uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.internships i join public.internship_tutors t on t.internship_id=i.id where i.student_id=s and t.tutor_id=auth.uid() and t.accepted_at is not null); $$;
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.organizations enable row level security; alter table public.activities enable row level security; alter table public.competency_domains enable row level security; alter table public.competencies enable row level security; alter table public.internships enable row level security; alter table public.internship_tutors enable row level security; alter table public.internship_hours enable row level security; alter table public.experiences enable row level security; alter table public.evaluations enable row level security; alter table public.evidence_files enable row level security;
create policy "profiles self or staff" on public.profiles for select to authenticated using(id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or public.assigned_to_student(id));
create policy "profile self update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "roles self read admin manage" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "organizations read auth" on public.organizations for select to authenticated using(true);
create policy "organizations create auth" on public.organizations for insert to authenticated with check(true);
create policy "activities read auth" on public.activities for select to authenticated using(true);
create policy "domains read auth" on public.competency_domains for select to authenticated using(true);
create policy "competencies read auth" on public.competencies for select to authenticated using(true);
create policy "internship read assigned" on public.internships for select to authenticated using(student_id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or public.assigned_to_student(student_id));
create policy "student create internship" on public.internships for insert to authenticated with check(student_id=auth.uid());
create policy "internship update owner staff" on public.internships for update to authenticated using(student_id=auth.uid() or public.has_role('teacher') or public.has_role('admin')) with check(student_id=auth.uid() or public.has_role('teacher') or public.has_role('admin'));
create policy "tutor links read" on public.internship_tutors for select to authenticated using(tutor_id=auth.uid() or public.has_role('teacher') or public.has_role('admin'));
create policy "hours read assigned" on public.internship_hours for select to authenticated using(exists(select 1 from public.internships i where i.id=internship_id and (i.student_id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or public.assigned_to_student(i.student_id))));
create policy "hours student create" on public.internship_hours for insert to authenticated with check(exists(select 1 from public.internships i where i.id=internship_id and i.student_id=auth.uid()));
create policy "experience read assigned" on public.experiences for select to authenticated using(student_id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or public.assigned_to_student(student_id));
create policy "experience owner insert" on public.experiences for insert to authenticated with check(student_id=auth.uid());
create policy "experience owner update delete" on public.experiences for all to authenticated using(student_id=auth.uid()) with check(student_id=auth.uid());
create policy "evaluation read assigned" on public.evaluations for select to authenticated using(student_id=auth.uid() or evaluator_id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or public.assigned_to_student(student_id));
create policy "evaluation insert self or assigned staff" on public.evaluations for insert to authenticated with check(evaluator_id=auth.uid() and (student_id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or public.assigned_to_student(student_id)));
create policy "evidence owner read" on public.evidence_files for select to authenticated using(owner_id=auth.uid() or public.has_role('teacher') or public.has_role('admin') or exists(select 1 from public.experiences e where e.id=experience_id and public.assigned_to_student(e.student_id)));
create policy "evidence owner insert" on public.evidence_files for insert to authenticated with check(owner_id=auth.uid());
